'use client'

import Link from 'next/link'

import { setupSongGallery } from '@/app/actions/song_modify'
import { useEffect, useState } from 'react'

export default function Home() {
  const [songArray, setSongs] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function fetchSongs() {
      try {
        const dataArray = await setupSongGallery()

        setSongs(dataArray)
        console.log(songArray)
      } catch (err) {
        console.error(err)
      } finally {
        setLoading(false)
      }
    }

    fetchSongs()
  }, [])  
  return (
  <>
    <main>
      {loading && <div>wczytywanie piosenek</div>}
      {!loading && songArray.map(song => (
          <Link key={song.id} href={"./display?id=" + song.id}>
            <h2>{song.title}</h2>
            <p>{song.artist}</p>
          </Link>
      ))}
    </main>
  </>
  )
}
